// =====================================================
// 📥 CONTEXTO INICIAL
// =====================================================
const ctx = $input.first().json || {};
const headers = ctx.headers || {};

// Método HTTP (una sola vez)
const httpMethod = (ctx.method || "").toUpperCase();

// ⛔ Bloquear GET con query (bots)
if (httpMethod === "GET" && ctx.query) {
  return [];
}

// Entrada flexible: query, body o json
const data =
  ctx.query ||
  ctx.body ||
  ctx ||
  {};

// =====================================================
// 🧰 HELPERS
// =====================================================
const deburr = (s = "") =>
  s.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const lower = (s = "") => deburr(String(s)).toLowerCase();

// =====================================================
// 🌐 IP REAL
// =====================================================
function getIp() {
  try {
    const raw =
      headers["x-forwarded-for"] ||
      headers["X-Forwarded-For"] ||
      data.ip ||
      data.IP ||
      "";
    return String(raw).split(",")[0].trim();
  } catch {
    return "";
  }
}

// =====================================================
// 🔗 WEBHOOK URL
// =====================================================
function buildWebhookUrl() {
  try {
    const explicit = String(ctx.webhookUrl ?? data.webhookUrl ?? "").trim();
    if (explicit) return explicit;

    const proto =
      String(headers["x-forwarded-proto"] || headers["X-Forwarded-Proto"] || "")
        .toLowerCase() || "https";
    const host =
      String(
        headers["x-forwarded-host"] ||
          headers["X-Forwarded-Host"] ||
          headers["host"] ||
          headers["Host"] ||
          ""
      );
    if (host) return `${proto}://${host}`;
    return "";
  } catch {
    return "";
  }
}

// =====================================================
// 📊 DATOS BASE
// =====================================================
const nombre = (data.Name ?? data.nombre ?? "").trim();
const email = (data.Email ?? data.email ?? "").trim();
const telefonoRaw = String(data.Phone ?? data.telefono ?? "");
const empresa = (data.Company ?? data.empresa ?? "").trim();
const industria = String(data.Industry ?? data.industria ?? "").trim();
const personas = String(data.Employed ?? data.personas ?? "").trim();
const paisRaw = String(data.Country ?? data.pais ?? "").trim();
const facturacion = String(data.Pricing ?? data.facturacion ?? "").trim();
const RUC = String(data.RUC ?? data.DNI ?? "").trim();
const ip = getIp();
const webhookUrl = buildWebhookUrl();

// =====================================================
// 🔒 CAMPOS OBLIGATORIOS (TODOS)
// =====================================================
const requiredFields = {
  nombre,
  email,
  telefonoRaw,
  empresa,
  industria,
  personas,
  paisRaw,
  facturacion,
  RUC
};

const missingFields = Object.entries(requiredFields)
  .filter(([_, value]) => !value || String(value).trim().length === 0)
  .map(([key]) => key);

if (missingFields.length > 0) {
  return [];
}

// =====================================================
// 🔒 VALIDACIÓN DURA DEL NOMBRE (NO URL / NO EMOJI)
// =====================================================
const urlPattern = /(https?:\/\/|www\.|[a-z0-9-]+\.(com|net|org|ru|xyz|info|io))/i;
const emojiPattern = /[\u{1F300}-\u{1FAFF}]/u;
const nombreHumanoPattern = /^[a-zA-ZÀ-ÿÑñ\s'.-]{3,}$/;

if (
  urlPattern.test(nombre) ||
  emojiPattern.test(nombre) ||
  !nombreHumanoPattern.test(nombre)
) {
  return [];
}

// =====================================================
// 📧 CORREO EMPRESARIAL (CLASIFICACIÓN)
// =====================================================
const freeDomains = new Set([
  "gmail.com",
  "yahoo.com",
  "hotmail.com",
  "outlook.com",
  "live.com",
  "icloud.com",
  "aol.com",
  "protonmail.com",
  "msn.com",
  "yandex.com",
  "gmx.com",
  "zoho.com"
]);

let esCorreoEmpresarial = false;
{
  const parts = email.split("@");
  if (parts.length === 2) {
    const dom = parts[1].toLowerCase();
    esCorreoEmpresarial = !!dom && dom.includes(".") && !freeDomains.has(dom);
  }
}

// =====================================================
// 🏭 INDUSTRIA (CLASIFICACIÓN, NO BLOQUEO)
// =====================================================
const industriaNorm = lower(industria);
const esIndustriaValida =
  industriaNorm !== "otro" &&
  industriaNorm !== "otros";


// =====================================================
// 📞 TELÉFONO (E.164)
// =====================================================
const countryCodes = {
  ecuador: "+593",
  mexico: "+52",
  chile: "+56",
  venezuela: "+58",
  argentina: "+54",
  panama: "+507",
  colombia: "+57",
  peru: "+51"
};

function normalizePhone(rawPhone, rawCountry) {
  let digits = String(rawPhone).replace(/\D/g, "");
  const cc = countryCodes[lower(rawCountry)] ?? "+593";
  const ccDigits = cc.slice(1);

  if (digits.startsWith(ccDigits)) return "+" + digits;
  if (digits.startsWith("0")) digits = digits.slice(1);
  return cc + digits;
}

const telefonoNormalizado = normalizePhone(telefonoRaw, paisRaw);

function validarTelefono(e164) {
  if (!e164.startsWith("+")) return false;
  const d = e164.slice(1);
  return d.length >= 9 && d.length <= 15;
}

const esTelefonoValido = validarTelefono(telefonoNormalizado);
if (!esTelefonoValido) {
  return [];
}

// =====================================================
// 🛑 ANTI-SPAM FORMULARIO
// =====================================================

// Solo POST
if (httpMethod && httpMethod !== "POST") {
  return [];
}

// Honeypot
if (String(data.website || "").trim() !== "") {
  return [];
}

// Tiempo mínimo humano
const now = Date.now();
const formStart = Number(data.form_start_ts || 0);
if (formStart && now - formStart < 3000) {
  return [];
}

// =====================================================
// 🎯 MQL (SOLO PREPARADO, NO DECIDE NEGOCIO)
// =====================================================
const MQL = false;

// =====================================================
// ✅ SALIDA FINAL (LEAD LIMPIO)
// =====================================================
return [
  {
    json: {
      nombre,
      email,
      telefonoNormalizado,
      empresa,
      industria,
      personas,
      pais: paisRaw,
      facturacion,
      RUC,
      ip,
      webhookUrl,

      esCorreoEmpresarial,
      esIndustriaValida,
      esTelefonoValido,
      MQL
    }
  }
];

const data = $input.first().json;

// ==========================================================
// EXCEPCIÓN ESPECIAL → SI EL RUC NO SE ENVIÓ
// ERROR PERMITIDO (NO DEBE CORTAR EL FLUJO)
// ==========================================================
const errorMsg = data?.error?.message ?? "";

if (
    typeof errorMsg === "string" &&
    errorMsg.includes("El parámetro número RUC es requerido")
) {
    return [
        {
            json: {
                status: "OK",
                info: "RUC no enviado → se permite continuar"
            }
        }
    ];
}

// ==========================================================
// VALIDACIÓN NORMAL DE ERRORES
// ==========================================================
if (
    data.error &&
    typeof data.error.message === "string" &&
    data.error.message.trim() !== ""
) {
    return [
        {
            json: {
                status: "ERROR",
                errorMessage: data.error.message,
                errorName: data.error.name,
                errorCode: data.error.code
            }
        }
    ];
}

// ==========================================================
// SI NO HAY ERROR → OK NORMAL
// ==========================================================
return [
    {
        json: {
            status: "OK"
        }
    }
];

const ruc = String($json.RUC || "").trim();

return [{
  json: {
    ruc_sri: ruc
  }
}];

